# Example of handling empty input arrays and invalid data types
def validate_input(data):
    phone_numbers = data.get('phone_numbers')
    if not phone_numbers or not isinstance(phone_numbers, list):
        raise ValueError('Invalid request: Missing or invalid phone numbers')

# Example usage
try:
    validate_input({'phone_numbers': []})
except ValueError as e:
    print(e)  # Output: Invalid request: Missing or invalid phone numbers
